/**
* Rounds a single-precision floating-point number to the nearest multiple of `10^n`.
*
* ## Notes
*
* - When operating on floating-point numbers in bases other than `2`, rounding to specified digits can be inexact.
*
* @param x - input value
* @param n - integer power of `10`
* @returns rounded value
*
* @example
* // Round a value to 2 decimal places:
* var v = roundnf( 3.141592, -2 );
* // returns 3.14
*
* @example
* // If n = 0, `roundnf` behaves like `roundf`:
* var v = roundnf( 3.141592, 0 );
* // returns 3.0
*
* @example
* // Round a value to the nearest hundred:
* var v = roundnf( 1234.56, 2 );
* // returns 1200.0
*/
declare function roundnf( x: number, n: number ): number;


// EXPORTS //

export = roundnf;
